arguments.file_text:
@page "/board"
@using sv_4d96758e2bcd4caeb35b6102b5de487d.Components.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2>Project Board</h2>

@if (loading)
{
    <p class="board-loading">Loading tasks…</p>
}
else if (errorMessage is not null)
{
    <p class="board-error">@errorMessage</p>
}
else
{
    <BoardStats Tasks="tasks" />
    <TaskSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="kanban-board">
        @foreach (var col in columns)
        {
            var colIndex = Array.IndexOf(columns, col);
            var colTasks = FilteredTasks.Where(t => t.Status == col).ToList();

            <KanbanColumn Title="@col"
                          Status="@col"
                          Tasks="colTasks"
                          CanMoveLeft="colIndex > 0"
                          CanMoveRight="colIndex < columns.Length - 1"
                          OnMoveLeft="t => MoveTask(t, columns[colIndex - 1])"
                          OnMoveRight="t => MoveTask(t, columns[colIndex + 1])"
                          OnTaskCreated="HandleTaskCreated" />
        }
    </div>
}

@code {
    private List<TaskItem> tasks = new();
    private string searchText = "";
    private bool loading = true;
    private string? errorMessage;

    private static readonly string[] columns = { "To Do", "In Progress", "Done" };

    private IEnumerable<TaskItem> FilteredTasks =>
        string.IsNullOrWhiteSpace(searchText)
            ? tasks
            : tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        try
        {
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private void HandleSearchChanged(string value) => searchText = value;

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            // Replace the task in the list with the updated status
            var index = tasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                tasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleTaskCreated(AddTaskForm.NewTaskRequest request)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(request.Title, request.Assignee, request.Priority, request.DueDate);
            // The service creates with default status; override to match the column
            tasks.Add(created with { Status = request.Status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

/* Board page layout */
.kanban-board {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-loading,
.board-error {
    padding: 1rem;
    font-size: 1.1rem;
}

.board-error {
    color: #dc3545;
}

/* Stats bar */
.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 0.75rem 1rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
    border-radius: 6px;
}

.stat {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.stat-label {
    font-size: 0.8rem;
    color: #6c757d;
    text-transform: uppercase;
}

.stat-value {
    font-size: 1.4rem;
    font-weight: 600;
}

.stat-overdue .stat-value {
    color: #dc3545;
}

/* Search bar */
.search-bar {
    margin-bottom: 1rem;
}

.search-bar input {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.95rem;
}

/* Kanban column */
.kanban-column {
    flex: 1;
    min-width: 250px;
    background: #f1f3f5;
    border-radius: 8px;
    display: flex;
    flex-direction: column;
}

.column-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    border-bottom: 2px solid #dee2e6;
}

.column-header h3 {
    margin: 0;
    font-size: 1rem;
}

.task-count {
    background: #dee2e6;
    border-radius: 12px;
    padding: 0.1rem 0.6rem;
    font-size: 0.85rem;
    font-weight: 600;
}

.column-body {
    padding: 0.5rem;
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.column-footer {
    padding: 0.5rem;
}

/* Task card */
.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 0.4rem;
}

.task-title {
    font-weight: 600;
    font-size: 0.95rem;
}

.priority-badge {
    font-size: 0.7rem;
    padding: 0.15rem 0.5rem;
    border-radius: 10px;
    font-weight: 600;
    text-transform: uppercase;
}

.priority-high {
    background: #f8d7da;
    color: #842029;
}

.priority-medium {
    background: #fff3cd;
    color: #664d03;
}

.priority-low {
    background: #d1e7dd;
    color: #0f5132;
}

.task-assignee {
    font-size: 0.85rem;
    color: #6c757d;
    margin-bottom: 0.25rem;
}

.task-due {
    font-size: 0.8rem;
    color: #6c757d;
    margin-bottom: 0.5rem;
}

.task-actions {
    display: flex;
    gap: 0.4rem;
}

.btn-move {
    font-size: 0.75rem;
    padding: 0.25rem 0.5rem;
    border: 1px solid #ced4da;
    background: #fff;
    border-radius: 4px;
    cursor: pointer;
}

.btn-move:hover {
    background: #e9ecef;
}

/* Add task */
.btn-add-task {
    width: 100%;
    padding: 0.5rem;
    background: transparent;
    border: 2px dashed #ced4da;
    border-radius: 6px;
    color: #6c757d;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-add-task:hover {
    border-color: #adb5bd;
    color: #495057;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.add-task-form input,
.add-task-form select {
    padding: 0.4rem 0.5rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 0.85rem;
}

.form-actions {
    display: flex;
    gap: 0.4rem;
}

.btn-save,
.btn-cancel {
    flex: 1;
    padding: 0.4rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-save {
    background: #0d6efd;
    color: #fff;
}

.btn-save:hover {
    background: #0b5ed7;
}

.btn-cancel {
    background: #e9ecef;
    color: #495057;
}

.btn-cancel:hover {
    background: #dee2e6;
}

